<script setup>
import AppShell from '../../Components/AppShell.vue'
import { Head, useForm } from '@inertiajs/vue3'
import { ref } from 'vue'
import { ShieldCheck, Plus, Pencil, Trash2, X } from '@lucide/vue'

const props = defineProps({ roles: Array, permissions: Array, users: Array })
const editing = ref(null)
const showForm = ref(false)
const form = useForm({ name: '', display_name: '', description: '', permission_ids: [], user_ids: [] })
const openCreate = () => { editing.value = null; form.reset(); form.clearErrors(); showForm.value = true }
const openEdit = (role) => { editing.value = role; form.name = role.name; form.display_name = role.display_name; form.description = role.description || ''; form.permission_ids = role.permissions.map((p) => p.id); form.user_ids = role.users.map((u) => u.id); form.clearErrors(); showForm.value = true }
const submit = () => {
  const options = { preserveScroll: true, onSuccess: () => { showForm.value = false; form.reset() } }
  if (editing.value) form.put(`/settings/roles/${editing.value.id}`, options)
  else form.post('/settings/roles', options)
}
const remove = (role) => { if (window.confirm(`¿Eliminar el rol ${role.display_name}?`)) form.delete(`/settings/roles/${role.id}`, { preserveScroll: true }) }
</script>

<template><AppShell><Head title="Roles y permisos" /><div class="mx-auto max-w-6xl space-y-5">
  <header class="flex items-end justify-between gap-4"><div><h1 class="text-3xl font-bold">Roles y permisos</h1><p class="mt-1 text-sm text-slate-600">Perfiles reutilizables para administrar el acceso del equipo.</p></div><button class="inline-flex min-h-11 items-center gap-2 rounded-xl bg-violet-600 px-4 text-sm font-bold text-white" @click="openCreate"><Plus class="size-4" />Nuevo rol</button></header>
  <div v-if="$page.props.flash?.success" class="rounded-xl border border-emerald-200 bg-emerald-50 px-4 py-3 text-sm font-semibold text-emerald-800">{{ $page.props.flash.success }}</div><div v-if="$page.props.errors?.role" class="rounded-xl border border-red-200 bg-red-50 px-4 py-3 text-sm font-semibold text-red-800">{{ $page.props.errors.role }}</div>
  <section class="grid gap-4 md:grid-cols-2 xl:grid-cols-3"><article v-for="role in roles" :key="role.id" class="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm"><div class="flex items-start justify-between"><div class="flex size-11 items-center justify-center rounded-xl bg-violet-50 text-violet-700"><ShieldCheck class="size-5" /></div><div class="flex gap-1"><button class="rounded-lg p-2 text-blue-700 hover:bg-blue-50" @click="openEdit(role)"><Pencil class="size-4" /></button><button class="rounded-lg p-2 text-red-600 hover:bg-red-50" @click="remove(role)"><Trash2 class="size-4" /></button></div></div><h2 class="mt-4 font-bold">{{ role.display_name }}</h2><p class="text-xs font-mono text-slate-500">{{ role.name }}</p><p class="mt-2 min-h-10 text-sm text-slate-600">{{ role.description || 'Sin descripción' }}</p><div class="mt-3 flex flex-wrap gap-1"><span v-for="permission in role.permissions" :key="permission.id" class="rounded-full bg-slate-100 px-2 py-1 text-[11px]">{{ permission.display_name }}</span></div><p class="mt-4 text-xs font-semibold text-violet-700">{{ role.users_count }} usuario(s)</p></article><div v-if="!roles.length" class="rounded-2xl border border-dashed border-slate-300 bg-white p-10 text-center text-slate-500 md:col-span-2">Aún no hay roles configurados.</div></section>

  <div v-if="showForm" class="fixed inset-0 z-50 flex items-center justify-center bg-slate-950/50 p-4" @click.self="showForm = false"><form class="max-h-[92vh] w-full max-w-2xl overflow-y-auto rounded-2xl bg-white p-5 shadow-2xl" @submit.prevent="submit"><div class="flex items-center justify-between"><h2 class="text-xl font-bold">{{ editing ? 'Editar rol' : 'Nuevo rol' }}</h2><button type="button" class="rounded-lg p-2 hover:bg-slate-100" @click="showForm = false"><X class="size-5" /></button></div><div class="mt-4 grid gap-3 sm:grid-cols-2"><label class="text-sm font-semibold">Nombre visible<input v-model="form.display_name" class="mt-1 min-h-11 w-full rounded-xl border-slate-200" required></label><label class="text-sm font-semibold">Identificador<input v-model="form.name" pattern="[a-z0-9_-]+" placeholder="ej. supervisor_planta" class="mt-1 min-h-11 w-full rounded-xl border-slate-200" required></label><label class="text-sm font-semibold sm:col-span-2">Descripción<textarea v-model="form.description" class="mt-1 w-full rounded-xl border-slate-200"></textarea></label></div><p v-if="form.errors.name || form.errors.display_name" class="mt-2 text-xs text-red-600">{{ form.errors.name || form.errors.display_name }}</p><h3 class="mt-5 text-sm font-bold">Permisos</h3><div class="mt-2 grid gap-2 sm:grid-cols-2"><label v-for="permission in permissions" :key="permission.id" class="flex items-center gap-2 rounded-xl bg-slate-50 p-3 text-sm"><input v-model="form.permission_ids" type="checkbox" :value="permission.id" class="rounded">{{ permission.display_name }}</label></div><p v-if="form.errors.permission_ids" class="mt-2 text-xs text-red-600">{{ form.errors.permission_ids }}</p><h3 class="mt-5 text-sm font-bold">Usuarios asignados</h3><div class="mt-2 grid gap-2 sm:grid-cols-2"><label v-for="user in users" :key="user.id" class="flex items-center gap-2 rounded-xl border border-slate-200 p-3 text-sm"><input v-model="form.user_ids" type="checkbox" :value="user.id" class="rounded"><span>{{ user.name }} <small class="text-slate-500">@{{ user.username }}</small></span></label></div><button class="mt-5 min-h-11 w-full rounded-xl bg-violet-600 font-bold text-white" :disabled="form.processing">Guardar rol</button></form></div>
</div></AppShell></template>
